// E3.6 the coach's agent as it touches a contract: fee terms, client acceptance, shared representation.
// Agent people (fields, network, client list) are generated by K8 (front-office); this module reads them.
import { cparam } from './params.ts';

export interface AgentView {
  readonly id: number;
  readonly feeShare: number;
  /** Hidden 0 to 100 internal value; the user sees only the agent's record of past deals. */
  readonly negotiationSkill: number;
  readonly clientIds: readonly number[];
  /** Lowest rung this agent takes on (top agents decline a rung 2 coach). */
  readonly minClientRung: number;
}

export function agentTakesClient(a: AgentView, coachRung: number): boolean {
  return coachRung >= a.minClientRung;
}

export interface SharedRepresentation {
  readonly shared: boolean;
  /** E3.6.3: bonus to the coach's candidate score at that club. */
  readonly candidateBonus: number;
  /** E3.6.3: the agent's effective negotiation skill at that club. */
  readonly effectiveSkill: number;
}

/** The agent also represents the club's general manager or the owner's adviser: easier to get hired, softer on terms. */
export function sharedRepresentation(a: AgentView, clubDecisionMakerIds: readonly number[]): SharedRepresentation {
  const shared = clubDecisionMakerIds.some((id) => a.clientIds.includes(id));
  return shared
    ? { shared, candidateBonus: cparam('sharedAgentCandidateBonus'), effectiveSkill: Math.max(0, a.negotiationSkill - cparam('sharedAgentSkillPenalty')) }
    : { shared, candidateBonus: 0, effectiveSkill: a.negotiationSkill };
}

/** Clubs where three or more football decision makers share one agency (E3.6.3 acceptance helper). */
export function sameAgencyClusters(staffAgents: ReadonlyMap<number, readonly (number | null)[]>, min = 3): number[] {
  const out: number[] = [];
  for (const [club, agents] of staffAgents) {
    const counts = new Map<number, number>();
    for (const a of agents) if (a !== null) counts.set(a, (counts.get(a) ?? 0) + 1);
    if ([...counts.values()].some((n) => n >= min)) out.push(club);
  }
  return out;
}
